import { addDays } from "./billing"
import { FollowUpStatus, type ClientFollowUp } from "../../types/work-crm"

/** When a follow-up is due, from the reader's day: the buckets of the list (CRM step 5). */
export type FollowUpWhen = "late" | "today" | "week" | "later" | "done"

export const FOLLOW_UP_WHEN: readonly FollowUpWhen[] = ["late", "today", "week", "later", "done"]

export function followUpWhen(f: ClientFollowUp, today: string): FollowUpWhen {
  if (f.doneAt) return "done"
  if (f.dueDate < today) return "late"
  if (f.dueDate === today) return "today"
  return f.dueDate <= addDays(today, 7) ? "week" : "later"
}

export const followUpStatus = (f: ClientFollowUp) => f.status ?? FollowUpStatus.TODO

/** Open ones first by due date, then the done ones, latest first. */
export function sortFollowUps(list: ClientFollowUp[]) {
  return [...list].sort((a, b) => {
    if (!!a.doneAt !== !!b.doneAt) return a.doneAt ? 1 : -1
    if (a.doneAt && b.doneAt) return b.doneAt.localeCompare(a.doneAt)
    return a.dueDate.localeCompare(b.dueDate) || a.id.localeCompare(b.id)
  })
}

export interface FollowUpCounts {
  open: number
  late: number
  today: number
  week: number
  /** Done in the last 30 days */
  doneRecently: number
}

export function followUpCounts(list: ClientFollowUp[], today: string): FollowUpCounts {
  const since = addDays(today, -30)
  const c: FollowUpCounts = { open: 0, late: 0, today: 0, week: 0, doneRecently: 0 }
  for (const f of list) {
    const when = followUpWhen(f, today)
    if (when === "done") {
      if (f.doneAt!.slice(0, 10) >= since) c.doneRecently++
      continue
    }
    c.open++
    if (when === "late") c.late++
    else if (when === "today") c.today++
    else if (when === "week") c.week++
  }
  return c
}

/**
 * Who may change a follow-up: people who can edit clients, and its owner
 * (marking it done or in progress from My work without client rights).
 */
export function canWorkOn(f: ClientFollowUp, me: string | undefined, canEditClients: boolean) {
  return canEditClients || (!!me && f.ownerId === me)
}
